import { test, expect } from '@playwright/test';

test.describe('Faceted Search - Results Update Without Full Page Reload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should update search results when a facet filter is applied without full page reload', async ({ page }) => {
    // Verify initial search results are displayed
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();
    const resultItems = page.getByRole('listitem');
    await expect(resultItems).toHaveCount(10);

    // Apply a facet filter using getByRole
    const categoryFilter = page.getByRole('button', { name: /category/i });
    await categoryFilter.click();
    const electronicsFacet = page.getByRole('option', { name: /electronics/i });
    await electronicsFacet.click();

    // Verify results update without page reload
    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    // Verify results container is still visible and updated
    await expect(resultsContainer).toBeVisible();
    const updatedResultItems = page.getByRole('listitem');
    await expect(updatedResultItems).toHaveCount(5);

    // Verify the filter is active
    const activeFilter = page.getByText('Electronics');
    await expect(activeFilter).toBeVisible();
  });

  test('should handle multiple facet filters and maintain search context without page reload', async ({ page }) => {
    // Perform initial search
    const searchInput = page.getByPlaceholder('Search products...');
    await searchInput.fill('laptop');
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Apply first facet filter (Brand)
    const brandFilter = page.getByRole('button', { name: /brand/i });
    await brandFilter.click();
    const appleFacet = page.getByRole('option', { name: /apple/i });
    await appleFacet.click();

    // Apply second facet filter (Price Range)
    const priceFilter = page.getByRole('button', { name: /price range/i });
    await priceFilter.click();
    const priceRangeOption = page.getByRole('option', { name: /500-1000/i });
    await priceRangeOption.click();

    // Verify results update with both filters applied
    await page.waitForResponse(response => 
      response.url().includes('/api/search') && response.status() === 200
    );

    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();
    const resultItems = page.getByRole('listitem');
    await expect(resultItems).toHaveCount(2);

    // Verify both filters are active
    const activeBrand = page.getByText('Apple');
    await expect(activeBrand).toBeVisible();
    const activePrice = page.getByText('$500 - $1000');
    await expect(activePrice).toBeVisible();

    // Verify no full page reload occurred
    const pageUrl = page.url();
    expect(pageUrl).toContain('/search');
  });
});
